const props = p => p.properties || {};
const text = v => !v ? "" : v.title ? v.title.map(t=>t.plain_text).join("") : v.rich_text ? v.rich_text.map(t=>t.plain_text).join("")
  : v.select ? (v.select.name||"") : v.status ? (v.status.name||"") : v.number!=null ? String(v.number) : v.checkbox!=null ? String(v.checkbox) : "";
const titleOf = p => { for (const k in props(p)) if (props(p)[k].type==="title") return text(props(p)[k]); return ""; };
const find = (p, re) => { for (const k in props(p)) if (re.test(k)) return text(props(p)[k]); return ""; };


const ORDER = ["Booked","In Progress","Awaiting Invoice","Flagged","Paid"];
const stages = Object.fromEntries(ORDER.map(s=>[s,[]]));
for (const it of $input.all().filter(i=>i.json.id)) { const p = it.json;
  const stage = find(p,/^status$/i) || "Booked";
  const when = props(p)["Scheduled Date"]?.date?.start || "";
  (stages[stage] = stages[stage] || []).push({ title: titleOf(p) || "(untitled)", sub: [find(p,/^job type$/i), when].filter(Boolean).join(" · ") }); }
return [{ json: { body: { stages: Object.entries(stages).map(([name,cards])=>({name,cards})) } } }];

